def merge_intervals(intervals):
    if not intervals:
        return []
    merged = []
    for start, end in sorted((iv[0], iv[1]) for iv in intervals):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    unique_edges = set(edges)
    indegree = {node: 0 for node in nodes}
    outgoing = {node: set() for node in nodes}

    for source, destination in unique_edges:
        indegree[destination] += 1
        outgoing[source].add(destination)

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)

    result = []
    while available:
        node = heapq.heappop(available)
        result.append(node)
        for neighbor in outgoing[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(available, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("weight out of range")
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current and current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re

def parse_env(text):
    result = {}
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f'Invalid line: {line!r}')
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key_re.fullmatch(key):
            raise ValueError(f'Invalid key: {key!r}')
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        result[key] = value
    return result

def parse_sse(chunks):
    s = b"".join(chunks).decode("utf-8")
    events = []
    current = []
    i = 0
    start = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == "\n":
            line = s[start:i]
            i += 1
            start = i
        elif c == "\r":
            line = s[start:i]
            if i + 1 < n and s[i + 1] == "\n":
                i += 2
            else:
                i += 1
            start = i
        else:
            i += 1
            continue
        if line.strip() == "":
            if current:
                data = "\n".join(current)
                current = []
                if data == "[DONE]":
                    return events
                events.append(data)
            continue
        if line.startswith(":"):
            continue
        if ":" in line:
            name, _, value = line.partition(":")
            if name == "data":
                if value.startswith(" "):
                    value = value[1:]
                current.append(value)
        elif line == "data":
            current.append("")
    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0
    if attempt >= 4096:
        # base >= 2**-1074, so base * 2**attempt > cap for any representable cap
        return float(cap)
    lc = math.log(cap)
    l = math.log(base) + attempt * math.log(2.0)
    if l > lc:
        return float(cap)
    return math.exp(l)

def fifo_admit(active, queued, budget, slots):
    if any(req > budget for req in queued):
        raise ValueError("queued reservation exceeds budget")

    admitted = []
    remaining = []
    token_used = sum(active)
    slots_used = len(active)

    for i, req in enumerate(queued):
        if slots_used < slots and token_used + req <= budget:
            admitted.append(req)
            token_used += req
            slots_used += 1
        else:
            remaining = list(queued[i:])
            break

    return admitted, remaining
